stack = []
MAX = 10

def push(item):
    if len(stack) == MAX:
        print("Stack overflow")
    else:
        stack.append(item)      # adds at the end = the top

def pop():
    if len(stack) == 0:
        print("Stack underflow")
        return None
    return stack.pop()          # removes from the end = the top

push(5); push(8)
print(stack[-1])               # peek → 8
print(pop())                   # 8
print(len(stack) == 0)         # is_empty → False
